+        assertThat(seqNoField.getStoredFieldBytes(), equalTo(0L));
+        assertThat(seqNoField.getPointsBytes(), greaterThan(0L));
+        assertThat(seqNoField.getDocValuesBytes(), greaterThan(0L));
+    }
+}

