+                @Override
+                public ClusterState execute(ClusterState currentState) {
+                    assertFalse(keepRunning.get());
+                    starvedTaskExecuted.countDown();
+                    return currentState;
+                }
+
+                @Override
+                public void onFailure(String source, Exception e) {
+                    fail();
+                }
+            });
